    #[test]
    fn member_requests_preserve_identifier_bounds() {
        for (value, expected) in [("1", 1), ("2147483647", i32::MAX as u32)] {
            assert_eq!(
                value.parse::<MemberDetailsRequest>().unwrap().id().value(),
                expected
            );
        }
        for value in ["", "0", "-1", "invalid", "2147483648", "4294967296"] {
