//! Funders give financial compensation to [`parliament_members`]

use std::str::FromStr;
use uuid::Uuid;

use strum::{AsRefStr, EnumString};

#[derive(Clone, Debug, PartialEq, Eq)]
/// Funder of MP declarations
pub struct Funder {
    id: FunderId,
    name: String,
    kind: FunderKind,
}

impl Funder {
    #[must_use]
    /// Creates a new instance
    pub const fn new(id: FunderId, name: String, funder_kind: FunderKind) -> Self {
        Self {
            id,
            name,
            kind: funder_kind,
        }
    }

    /// Persistent funder identity.
    #[must_use]
    pub const fn id(&self) -> FunderId {
        self.id
    }

    #[must_use]
    /// Gets funder name
    pub fn name(&self) -> &str {
        &self.name
    }

    #[must_use]
    /// Gets legal person
    pub fn kind(&self) -> &str {
        self.kind.as_ref()
    }
}

#[derive(Clone, Debug, AsRefStr, EnumString, PartialEq, Eq)]
/// All possible funder kinds
#[allow(missing_docs)] // Self explanatory
pub enum FunderKind {
    Company,
    Individual,
    Trust,
    #[strum(serialize = "Trade Union")]
    TradeUnion,
    Other,
    /// We don't know what this is supposed to be
    #[strum(serialize = "Not Specified")]
    NotSpecified,
    #[strum(serialize = "Building society")]
    BuildingSociety,
    #[strum(serialize = "Limited Liability Partnership")]
    LimitedLiabilityPartnership,
    #[strum(serialize = "Unincorporated association")]
    UnincorporatedAssociation,
    #[strum(serialize = "Friendly society")]
    FriendlySociety,
    #[strum(serialize = "Registered Party")]
    RegisteredParty,
}

/// Persistent exact-name funder identity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FunderId(Uuid);

impl FunderId {
    /// Wraps a database identity.
    #[must_use]
    pub const fn new(id: Uuid) -> Self {
        Self(id)
    }
    /// Database identity.
    #[must_use]
    pub const fn value(self) -> Uuid {
        self.0
    }
}

impl FromStr for FunderId {
    type Err = uuid::Error;
    fn from_str(value: &str) -> Result<Self, Self::Err> {
        value.parse().map(Self)
    }
}
import {
  memberIdPattern,
  funderIdPattern,
  type Total,
} from "../entity-details";
import type {
  DetailRoute,
  DetailState,
  MemberProfile,
  MemberDetails,
  FunderDetails,
  MemberDeclaration,
  FunderDeclaration,
  FundingEntry,
} from "../entity-details";
function malformed(): never {
  throw new Error("Details returned an unexpected response. Try again.");
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : malformed();
}
function text(value: unknown): string {
  return typeof value === "string" ? value : malformed();
}
function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : malformed();
}
function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : malformed();
}
function decimal(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
  return result;
}
function identity(value: unknown, kind: "MP" | "Funder"): string {
  const id = text(value);
  if (
    kind === "MP"
      ? !memberIdPattern.test(id) || Number(id) > 2147483647
      : !funderIdPattern.test(id)
  )
    return malformed();
  return id;
}
function memberProfile(value: unknown): MemberProfile {
  const row = record(value);
  if (typeof row.is_current_commons !== "boolean") return malformed();
  return {
    id: identity(row.id, "MP"),
    name: text(row.name),
    partyName: text(row.party_name),
    membershipFrom: text(row.membership_from),
    isCurrentCommons: row.is_current_commons,
  };
}
function integer(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value)
    ? value
    : malformed();
}
function timestamp(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !Number.isFinite(Date.parse(result)))
    return malformed();
  return result;
}
function declaration(value: unknown): MemberDeclaration {
  const row = record(value);
  return {
    sourceId: count(row.source_id),
    categoryId: integer(row.category_id),
    categoryName: text(row.category_name),
    registeredAt: timestamp(row.registered_at),
    entries: list(row.entries).map((value) => {
      const entry = record(value);
      const funder = entry.funder === null ? null : record(entry.funder);
      return {
        funder:
          funder === null
            ? null
            : { id: identity(funder.id, "Funder"), name: text(funder.name) },
        amount: decimal(entry.amount),
        currency: nullableText(entry.currency),
        paymentType: nullableText(entry.payment_type),
      };
    }),
  };
}
function declaredPeriod(value: unknown) {
  const row = record(value);
